        image: BurgerImage,
        content: 'Izgara sebze köftesi, avokado, marul, domates',
        price: 250,
    },
    {
        name: 'Çift Katlı Burger',
        image: BurgerImage,
        content: 'İki adet 150 gr dana köftesi, peynir, özel sos',
        price: 400,
    },
    {
        name: 'Balık Fillet Burger',
        image: BurgerImage,
        content: 'Kızarmış balık filetosi, tartar sos, marul',
        price: 280,
    },
    {
        name: 'Yunan Usulü Burger',
        image: BurgerImage,
        content: '200 gr dana köftesi, feta peyniri, zeytin, tzatziki',
        price: 330,
    },
    {
        name: 'Buffalo Tavuk Burger',
        image: BurgerImage,
        content: 'Baharatlı buffalo tavuk, mavi peynir sosu, kereviz',
        price: 290,
    },
    {
        name: 'Teriyaki Burger',
        image: BurgerImage,
        content: 'Izgara tavuk, teriyaki sosu, ananas',
        price: 310,
    },
    {
        name: 'Klasik Amerikan Burger',
        image: BurgerImage,
        content: 'Klasik dana köftesi, marul, domates, turşu',
        price: 260,
    },
    {
        name: 'Kahvaltı Burgeri',
